import os
import json
import time
import hashlib
import hmac
import secrets
import tempfile
import fcntl
from pathlib import Path


class SecureSessionStore:
    """File-based session store with cryptographic integrity verification."""

    SESSION_DIR = '/tmp/app_sessions'
    SESSION_LIFETIME = 3600  # 1 hour
    HMAC_KEY = None

    def __init__(self, hmac_key_path='/etc/app/session.key'):
        self._ensure_session_dir()
        self.HMAC_KEY = self._load_or_create_key(hmac_key_path)

    def _ensure_session_dir(self):
        os.makedirs(self.SESSION_DIR, mode=0o700, exist_ok=True)

    def _load_or_create_key(self, path):
        try:
            with open(path, 'rb') as f:
                key = f.read()
                if len(key) >= 32:
                    return key[:32]
        except (IOError, OSError):
            pass
        key = secrets.token_bytes(32)
        try:
            os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            try:
                os.write(fd, key)
            finally:
                os.close(fd)
        except (IOError, OSError):
            pass
        return key

    def _compute_mac(self, session_id, data_bytes):
        return hmac.new(self.HMAC_KEY, session_id.encode() + data_bytes, hashlib.sha256).digest()

    def _session_path(self, session_id):
        # Sanitize session_id to prevent path traversal
        safe_id = hashlib.sha256(session_id.encode()).hexdigest()
        return os.path.join(self.SESSION_DIR, f'sess_{safe_id}')

    def create_session(self, user_id, roles=None, metadata=None):
        """Create a new authenticated session."""
        session_id = secrets.token_urlsafe(32)
        session_data = {
            'session_id': session_id,
            'user_id': user_id,
            'roles': roles or [],
            'metadata': metadata or {},
            'created_at': time.time(),
            'expires_at': time.time() + self.SESSION_LIFETIME,
            'last_accessed': time.time()
        }
        self._persist_session(session_id, session_data)
        return session_id

    def _persist_session(self, session_id, session_data):
        """Write session data with integrity MAC."""
        data_bytes = json.dumps(session_data, sort_keys=True).encode('utf-8')
        mac = self._compute_mac(session_id, data_bytes)
        path = self._session_path(session_id)
        # Write atomically using temp file + rename
        tmp_fd, tmp_path = tempfile.mkstemp(dir=self.SESSION_DIR)
        try:
            with os.fdopen(tmp_fd, 'wb') as f:
                f.write(mac + b'\n' + data_bytes)
            os.rename(tmp_path, path)
        except Exception:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _read_session_atomic(self, path):
        """Read session file with exclusive lock to prevent TOCTOU."""
        try:
            fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        except (OSError, IOError):
            return None
        try:
            fcntl.flock(fd, fcntl.LOCK_SH)
            content = b''
            while True:
                chunk = os.read(fd, 4096)
                if not chunk:
                    break
                content += chunk
            return content
        except (OSError, IOError):
            return None
        finally:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(fd)

    def validate_and_get_session(self, session_id):
        """Validate session exists, has valid MAC, and is not expired.
        Returns session data if valid, None otherwise.
        Performs validation and retrieval atomically."""
        path = self._session_path(session_id)

        content = self._read_session_atomic(path)
        if content is None:
            return None

        if b'\n' not in content:
            self._delete_session_file(path)
            return None

        mac_stored, data_bytes = content.split(b'\n', 1)
        mac_computed = self._compute_mac(session_id, data_bytes)

        if not hmac.compare_digest(mac_stored, mac_computed):
            self._delete_session_file(path)
            return None

        try:
            session_data = json.loads(data_bytes)
        except (json.JSONDecodeError, ValueError):
            self._delete_session_file(path)
            return None

        # Check expiration - session is valid only if current time is strictly before expiry
        current_time = time.time()
        expires_at = session_data.get('expires_at', 0)

        if current_time >= expires_at:
            # Session expired, clean up
            self._delete_session_file(path)
            return None

        # Update last_accessed time atomically
        session_data['last_accessed'] = current_time
        self._persist_session(session_id, session_data)

        return session_data

    def _delete_session_file(self, path):
        try:
            os.unlink(path)
        except OSError:
            pass

    def revoke_session(self, session_id):
        """Revoke/delete a session."""
        path = self._session_path(session_id)
        self._delete_session_file(path)

    def check_permission(self, session_id, required_role):
        """Check if session holder has the required role."""
        session_data = self.validate_and_get_session(session_id)
        if session_data is None:
            return False

        user_roles = session_data.get('roles', [])
        return required_role in user_roles


class SessionMiddleware:
    """HTTP middleware for session-based authentication."""

    def __init__(self, store=None):
        self.store = store or SecureSessionStore()

    def authenticate_request(self, headers):
        """Extract and validate session from request headers."""
        auth_header = headers.get('Authorization', '')

        if not auth_header.startswith('Bearer '):
            return None, 'Missing or invalid Authorization header'

        session_id = auth_header[7:].strip()

        if not session_id or len(session_id) > 128:
            return None, 'Invalid session token format'

        session_data = self.store.validate_and_get_session(session_id)

        if session_data is None:
            return None, 'Session invalid or expired'

        return session_data, None

    def authorize_request(self, headers, required_role):
        """Authenticate and authorize in one step."""
        session_data, error = self.authenticate_request(headers)

        if error:
            return False, error

        user_roles = session_data.get('roles', [])
        if required_role not in user_roles:
            return False, f'Insufficient permissions: requires {required_role}'

        return True, None


# Password hashing parameters (PBKDF2-HMAC-SHA256)
PBKDF2_ITERATIONS = 200_000
PBKDF2_SALT_BYTES = 16
PBKDF2_DKLEN = 32


def _hash_password(password, salt):
    """Derive a slow, salted hash of the password using PBKDF2-HMAC-SHA256."""
    return hashlib.pbkdf2_hmac(
        'sha256', password.encode('utf-8'), salt, PBKDF2_ITERATIONS, dklen=PBKDF2_DKLEN
    )


def handle_admin_action(headers, action):
    """Example endpoint requiring admin role."""
    middleware = SessionMiddleware()
    authorized, error = middleware.authorize_request(headers, 'admin')

    if not authorized:
        return {'status': 403, 'error': error}

    return {'status': 200, 'result': f'Admin action {action} executed'}


def handle_login(username, password, user_db):
    """Example login endpoint that creates a session."""
    # Verify credentials
    user = user_db.get(username)
    if not user:
        # Perform a dummy PBKDF2 computation to keep timing consistent and
        # prevent user enumeration.
        _hash_password(password, b'\x00' * PBKDF2_SALT_BYTES)
        return {'status': 401, 'error': 'Invalid credentials'}

    # Expect stored salt (hex) and stored hash (hex) for salted PBKDF2 verification.
    stored_hash_hex = user.get('password_hash', '')
    salt_hex = user.get('password_salt', '')
    try:
        salt = bytes.fromhex(salt_hex)
    except (ValueError, TypeError):
        salt = b''

    provided_hash = _hash_password(password, salt) if salt else b''
    try:
        stored_hash = bytes.fromhex(stored_hash_hex)
    except (ValueError, TypeError):
        stored_hash = b''

    if not stored_hash or not hmac.compare_digest(stored_hash, provided_hash):
        return {'status': 401, 'error': 'Invalid credentials'}

    store = SecureSessionStore()
    session_id = store.create_session(
        user_id=username,
        roles=user.get('roles', []),
        metadata={'login_ip': '127.0.0.1'}
    )

    return {'status': 200, 'session_id': session_id}
